package career.assistant.application.service;
import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.jobscore.repository.JobScoreRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AutoApplyWorkerService {
 private final ApplicationRepository apps; private final JobScoreRepository scores; private final AutoApplyExecutionService execution; private final boolean enabled,dry,scheduler; private final java.math.BigDecimal minimum;
 public AutoApplyWorkerService(ApplicationRepository a,JobScoreRepository s,AutoApplyExecutionService e,@Value("${career.application.auto-apply-enabled:false}")boolean en,@Value("${career.application.dry-run:true}")boolean dr,@Value("${career.application.scheduler-enabled:false}")boolean sc,@Value("${career.application.minimum-score:75}")java.math.BigDecimal m){apps=a;scores=s;execution=e;enabled=en;dry=dr;scheduler=sc;minimum=m;}
 public WorkerResult run(boolean confirmation){if(!enabled)return new WorkerResult(WorkerOutcome.DISABLED,null,"Auto-apply is disabled");if(dry)return new WorkerResult(WorkerOutcome.DRY_RUN_PROTECTED,null,"Dry-run protection is enabled");if(!confirmation)return new WorkerResult(WorkerOutcome.REVIEW_REQUIRED,null,"Explicit confirmation is required");List<Application> candidates=apps.findByStatus(ApplicationStatus.READY_TO_APPLY).stream().filter(a->scores.findByJob(a.getJob()).map(s->s.getScore()!=null&&s.getScore().compareTo(minimum)>=0).orElse(false)).sorted(Comparator.comparing((Application a)->scores.findByJob(a.getJob()).map(s->s.getScore()).orElse(java.math.BigDecimal.ZERO),Comparator.reverseOrder()).thenComparing(a->Optional.ofNullable(a.getReviewedAt()).orElse(a.getCreatedAt()),Comparator.nullsLast(Comparator.naturalOrder())).thenComparing(Application::getId,Comparator.nullsLast(Comparator.naturalOrder()))).toList();if(candidates.isEmpty())return new WorkerResult(WorkerOutcome.NO_ELIGIBLE_APPLICATION,null,"No eligible READY_TO_APPLY application");var r=execution.execute(candidates.getFirst().getId(),true);if(r.state()==null)return new WorkerResult(WorkerOutcome.REVIEW_REQUIRED,r.applicationId(),r.blocker());if(r.state()==career.assistant.application.audit.SubmissionAttemptState.UNCERTAIN)return new WorkerResult(WorkerOutcome.UNCERTAIN,r.applicationId(),r.blocker());if(r.state()==career.assistant.application.audit.SubmissionAttemptState.REVIEW_REQUIRED)return new WorkerResult(WorkerOutcome.REVIEW_REQUIRED,r.applicationId(),r.blocker());return new WorkerResult(WorkerOutcome.PROCESSED,r.applicationId(),r.blocker());}
 public boolean schedulerAllowed(){return scheduler&&enabled&&!dry;} public enum WorkerOutcome{DISABLED,DRY_RUN_PROTECTED,NO_ELIGIBLE_APPLICATION,DAILY_LIMIT_REACHED,PROCESSED,REVIEW_REQUIRED,UNCERTAIN} public record WorkerResult(WorkerOutcome outcome,UUID applicationId,String safeReason){}
}
